static void nameChoice(const std::string& label,std::string& field,const std::vector<std::string>& names){int pick=0;auto it=std::find(names.begin(),names.end(),field);if(it!=names.end())pick=int(it-names.begin());if(combo(label,pick,names))field=names[pick];}
static void actionGroupChecks(Repo& r,std::vector<std::string>& active){for(size_t i=0;i<r.actionsGroups.size();i++){auto& name=r.actionsGroups[i].name;bool on=std::find(active.begin(),active.end(),name)!=active.end();if(checkbox(name+"##agcheck"+std::to_string(i),on)){if(on)active.push_back(name);else active.erase(std::remove(active.begin(),active.end(),name),active.end());}}}
static void entitySettings(){checkbox("Draw Self Connections",settings.drawSelfConnections);integer("Max Connections Draw Count",settings.maxConnectionsDrawCount);settings.maxConnectionsDrawCount=std::clamp(settings.maxConnectionsDrawCount,0,1024);line("Hold 1: Ban; hold 3: Exclusive; Shift: any face; RMB: cancel. Viewport editing requires the extended host.");}
static void editNames(std::vector<std::string>& names,const char* suffix){line("Built-in: Empty, Solid, Base");for(size_t i=0;i<names.size();i++){textInput(std::string("Name##")+suffix+std::to_string(i),names[i]);host->same_line();if(button(std::string("x##")+suffix+std::to_string(i))){names.erase(names.begin()+i);changed();break;}}if(button(std::string("+##")+suffix)&&names.size()<28){names.push_back(std::string("Group ")+std::to_string(names.size()+1));changed();}}
static void detach(Repo& r,BlockRef ref){for(auto& big:r.bigBlocks)for(auto& cell:big.data)cell.erase(std::remove(cell.begin(),cell.end(),ref),cell.end());if(auto v=variant(r,ref))v->bigBlockUid.clear();changed();}
